  -- 01. Interacciones clínicamente relevantes en IC y notificación de eventos adversos al INVIMA
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La interacción que descompensó al paciente","texto":"Un paciente con IC estable empieza un AINE y un antiarrítmico. A los días vuelve con edema, bradicardia y potasio alto. Las interacciones en IC pueden ser graves y difíciles de detectar. Revisarlas en la dispensación y notificar los eventos al INVIMA es parte de la seguridad."},"objetivos":["Reconocer interacciones relevantes en IC.","Priorizar las de mayor riesgo.","Aplicar medidas de prevención.","Notificar eventos adversos al INVIMA."],"conceptos":[{"icono":"AlertTriangle","termino":"Interacción","definicion":"Cambio en el efecto de un fármaco por otro, la dieta o una enfermedad."},{"icono":"Pill","termino":"AINE","definicion":"Retiene sodio y empeora la función renal."},{"icono":"Activity","termino":"Antiarrítmico","definicion":"Puede causar bradicardia o proarritmia."},{"icono":"FileCheck","termino":"Notificación","definicion":"Reporte de sospecha al programa o al INVIMA."}],"secciones":[{"titulo":"Interacciones frecuentes","parrafos":["Los AINE con IECA/ARA-II y diuréticos aumentan el riesgo de daño renal e hiperpotasemia. Los antiarrítmicos pueden causar bradicardia o proarritmia. Los corticoides retienen líquidos. Los suplementos de potasio y las sales de reemplazo pueden elevar el potasio.","Se revisan también las interacciones con digoxina, warfarina y fármacos que prolongan el QT."]},{"titulo":"Prevención","parrafos":["La revisión de la medicación completa en cada contacto detecta interacciones. Se proponen alternativas y se controlan electrolitos y función renal.","La comunicación con el equipo es clave."]},{"titulo":"Notificación","parrafos":["Las sospechas de reacciones adversas o problemas de calidad se notifican al programa de farmacovigilancia o al INVIMA. No se requiere certeza.","La documentación permite seguir y prevenir.","Para notificar se reúnen datos del paciente, el fármaco implicado, la reacción, la cronología y la evolución. En Colombia, el programa de farmacovigilancia del INVIMA recibe reportes de profesionales y pacientes. La notificación no implica culpa y ayuda a generar alertas. En IC, las combinaciones de AINE, IECA/ARA-II, diuréticos y espironolactona concentran la mayor parte de los eventos graves. También se revisan productos naturales, sales de reemplazo y suplementos de potasio, que el paciente no siempre menciona. La conciliación en cada transición reduce reingresos y permite educar con ejemplos concretos."]}],"errores":[{"error":"No preguntar por venta libre.","correccion":"AINE y suplementos son frecuentes."},{"error":"No controlar potasio.","correccion":"Riesgo de arritmias."},{"error":"No notificar.","correccion":"La farmacovigilancia protege."}],"comprueba":[{"pregunta":"¿Qué interacción es peligrosa?","respuesta":"AINE con IECA/ARA-II y diurético."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio, renal y ritmo."},{"pregunta":"¿Dónde se notifica?","respuesta":"Al programa o al INVIMA."}],"resumen":["Las interacciones en IC pueden ser graves.","La revisión completa las detecta.","El control de electrolitos es clave.","La notificación es parte de la seguridad."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"INVIMA. Alertas sanitarias.","url":"https://www.invima.gov.co/alertas-sanitarias"}],"imagenes":[{"ubicacion":"Sección de interacciones","descripcion":"Paciente con IC y varios medicamentos, con alertas de potasio, renal y ritmo.","alt":"Interacciones en insuficiencia cardíaca"}],"keywords":["interacciones insuficiencia cardíaca","aine ic","farmacovigilancia ic","notificación invima"],"mapa":{"centro":"Interacciones en IC","ramas":[{"titulo":"Fármacos","icono":"Pill","nodos":["AINE","Antiarrítmicos","Corticoides"]},{"titulo":"Electrolitos","icono":"Droplets","nodos":["Potasio","Sodio","Renal"]},{"titulo":"Ritmo","icono":"Activity","nodos":["Bradicardia","QT","Arritmia"]},{"titulo":"Reporte","icono":"FileCheck","nodos":["INVIMA","Documentar","Seguir"]}]},"proceso":{"titulo":"Cómo revisar interacciones","intro":"","pasos":[{"titulo":"Listar","detalle":"Todos los medicamentos y suplementos.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Priorizar","detalle":"Riesgo renal, potasio y ritmo.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Intervenir","detalle":"Alternativa o ajuste.","icono":"Pill","evidencia":"Nota."},{"titulo":"Controlar","detalle":"Electrolitos y renal.","icono":"LineChart","evidencia":"Resultados."},{"titulo":"Reportar","detalle":"Sospecha al INVIMA.","icono":"FileCheck","evidencia":"Reporte."}]},"caso":{"titulo":"AINE y antiarrítmico","contexto":"Paciente con IC que inicia AINE y antiarrítmico, con edema, bradicardia y potasio alto.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Mantener ambos.","correcta":false,"retro":"Pueden empeorar la IC."},{"texto":"Revisar interacciones, suspender lo riesgoso y notificar.","correcta":true,"retro":"La seguridad es prioritaria."},{"texto":"Aumentar el diurético sin revisar.","correcta":false,"retro":"No es suficiente."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Interacciones clínicamente relevantes en IC y notificación de eventos adversos al INVIMA$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
