  -- 02. Seguimiento farmacoterapéutico del paciente con IC: parámetros, adherencia, polifarmacia y continuidad
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El seguimiento que sostiene el tratamiento","texto":"La IC requiere ajustes frecuentes, educación y revisión de la medicación. Un paciente con cinco fármacos, ERC y dos hospitalizaciones necesita un seguimiento estructurado. El QF puede detectar problemas antes de que causen una descompensación."},"objetivos":["Aplicar el seguimiento farmacoterapéutico en IC.","Reconocer parámetros clave.","Manejar polifarmacia y adherencia.","Asegurar continuidad."],"conceptos":[{"icono":"Users","termino":"Seguimiento","definicion":"Evaluación continua de la farmacoterapia."},{"icono":"ClipboardList","termino":"Parámetros","definicion":"Peso, presión, síntomas, renal y potasio."},{"icono":"Layers","termino":"Polifarmacia","definicion":"Múltiples fármacos con riesgo de interacciones."},{"icono":"CalendarClock","termino":"Continuidad","definicion":"Coordinación entre niveles y acceso."}],"secciones":[{"titulo":"Parámetros","parrafos":["El seguimiento incluye peso, síntomas, presión, frecuencia, función renal, potasio y hemoglobina. La revisión de la medicación detecta omisiones, duplicidades e interacciones.","La documentación permite comparar y ajustar.","Los controles suelen ser frecuentes al inicio y tras cada cambio: a la una o dos semanas para presión, potasio y creatinina, y luego cada uno a tres meses según estabilidad. La clase funcional y la calidad de vida se documentan con instrumentos breves como la escala NYHA y el cuestionario KCCQ, que ayudan a detectar deterioro antes de la consulta. Se revisan también síntomas de hipotensión, mareo, tos o edema. La frecuencia se individualiza: más estrecha en enfermedad renal, adultos mayores y polifarmacia. En Colombia, las barreras de acceso, el copago y la entrega fraccionada afectan la continuidad; el QF puede anticipar fórmulas, verificar disponibilidad y proponer alternativas dentro del plan. Un buen seguimiento convierte datos aislados en decisiones oportunas y demuestra su valor con registros claros. La revisión tras la hospitalización debe ocurrir en la primera semana."]},{"titulo":"Adherencia y polifarmacia","parrafos":["La polifarmacia es frecuente. Se simplifica cuando es posible y se revisan barreras. La educación y los recordatorios mejoran la adherencia.","El QF puede detectar problemas y proponer cambios."]},{"titulo":"Continuidad","parrafos":["La coordinación entre hospital, farmacia y atención primaria evita interrupciones. La revisión temprana después de una hospitalización es clave.","La meta es un plan sostenible."]}],"errores":[{"error":"No revisar polifarmacia.","correccion":"Interacciones y duplicidades."},{"error":"No medir adherencia.","correccion":"Es parte del problema."},{"error":"No coordinar.","correccion":"La continuidad es clave."}],"comprueba":[{"pregunta":"¿Qué parámetros se revisan?","respuesta":"Peso, presión, renal, potasio y síntomas."},{"pregunta":"¿Qué es polifarmacia?","respuesta":"Uso de múltiples fármacos."},{"pregunta":"¿Cómo se asegura la continuidad?","respuesta":"Coordinación y seguimiento."}],"resumen":["El seguimiento es estructurado.","La polifarmacia se revisa.","La adherencia se mide.","La continuidad es clave."],"referencias":[{"cita":"Cipolle RJ, Strand LM, Morley PC. Pharmaceutical care practice: the patient-centered approach to medication management services. 3.ª ed. Nueva York: McGraw-Hill Medical; 2012.","url":"https://www.mhprofessional.com/pharmaceutical-care-practice-9780071759029-usa"},{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección del ciclo","descripcion":"Ciclo de seguimiento con ficha, medicación y parámetros.","alt":"Seguimiento farmacoterapéutico en IC"}],"keywords":["seguimiento farmacoterapéutico ic","polifarmacia insuficiencia cardíaca","adherencia ic"],"mapa":{"centro":"Seguimiento en IC","ramas":[{"titulo":"Clínico","icono":"Users","nodos":["Peso","Disnea","Edema"]},{"titulo":"Laboratorio","icono":"TestTube","nodos":["Renal","Potasio","Hemoglobina"]},{"titulo":"Medicación","icono":"Pill","nodos":["Adherencia","Interacciones","Dosis"]},{"titulo":"Continuidad","icono":"CalendarClock","nodos":["Citas","Acceso","Educación"]}]},"proceso":{"titulo":"Ciclo de seguimiento","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Síntomas y parámetros.","icono":"Search","evidencia":"Ficha."},{"titulo":"Revisar","detalle":"Medicación y adherencia.","icono":"Pill","evidencia":"Lista."},{"titulo":"Intervenir","detalle":"Ajuste o educación.","icono":"Lightbulb","evidencia":"Nota."},{"titulo":"Documentar","detalle":"Registrar y comunicar.","icono":"FileCheck","evidencia":"Registro."},{"titulo":"Seguir","detalle":"Programar control.","icono":"CalendarClock","evidencia":"Cita."}]},"caso":{"titulo":"Cinco fármacos y ERC","contexto":"Paciente con IC, ERC y cinco fármacos, mala adherencia y dos hospitalizaciones.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Solo dispensar.","correcta":false,"retro":"Se pierden oportunidades."},{"texto":"Revisar medicación, adherencia y parámetros, y coordinar.","correcta":true,"retro":"El seguimiento mejora resultados."},{"texto":"Aumentar todos los fármacos.","correcta":false,"retro":"No es seguro."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Seguimiento farmacoterapéutico del paciente con IC: parámetros, adherencia, polifarmacia y continuidad$t$ AND deleted_at IS NULL
