  -- 03. Educación al paciente con IC y autocuidado: signos de alarma, peso diario, sal, adherencia y vacunación
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El peso que avisa antes de la disnea","texto":"Un paciente con IC sube 2 kg en tres días y no consulta porque no tiene disnea. Al quinto día llega con edema y crepitantes. El peso diario es un signo temprano de congestión. La educación al paciente puede prevenir la hospitalización."},"objetivos":["Enseñar el autocuidado en IC.","Reconocer signos de alarma.","Aplicar el peso diario y la restricción de sal.","Reforzar adherencia y vacunación."],"conceptos":[{"icono":"Scale","termino":"Peso diario","definicion":"Aumento de 2 kg en 2-3 días sugiere retención."},{"icono":"Wheat","termino":"Sal","definicion":"Su reducción ayuda a la congestión."},{"icono":"AlertTriangle","termino":"Alarma","definicion":"Disnea, edema, ganancia de peso o mareo."},{"icono":"ShieldCheck","termino":"Vacunas","definicion":"Influenza, neumococo y COVID según indicación."}],"secciones":[{"titulo":"Peso y sal","parrafos":["El paciente debe pesarse a la misma hora y con la misma ropa. Un aumento de 2 kg en dos o tres días justifica consultar. La reducción de sal y de alimentos procesados ayuda a la congestión.","La educación debe ser práctica y adaptada a la cultura y al presupuesto."]},{"titulo":"Signos de alarma","parrafos":["La disnea en reposo o al esfuerzo, el edema creciente, el aumento de peso, el mareo, la palpitación o la disminución de la diuresis requieren consulta. El paciente debe tener un plan escrito.","La adherencia y la vacunación son parte del autocuidado."]},{"titulo":"Vacunación","parrafos":["La vacunación contra influenza, neumococo y COVID según indicación reduce complicaciones. El QF puede revisar el esquema.","La educación se refuerza en cada contacto.","La técnica teach-back, en la que el paciente explica con sus palabras qué hará, confirma la comprensión mejor que repetir instrucciones. Un plan escrito con metas pequeñas, horarios y teléfonos de contacto facilita la adherencia. Se adapta el lenguaje y se involucra al cuidador cuando hay deterioro cognitivo o visual. En la práctica colombiana conviene revisar la sal oculta en caldos, embutidos, quesos y alimentos enlatados, y proponer alternativas con especias y limón. La educación debe celebrar los logros y evitar mensajes culpabilizantes: el objetivo es sostener el autocuidado, no perfeccionarlo. Cada consulta es una oportunidad para reforzar un solo mensaje clave y verificar que se entendió. La familia y la red de apoyo también reciben orientación práctica."]}],"errores":[{"error":"No pesar todos los días.","correccion":"Es un signo temprano."},{"error":"No revisar sal oculta.","correccion":"Es la principal fuente."},{"error":"No revisar vacunas.","correccion":"Prevención de infecciones."}],"comprueba":[{"pregunta":"¿Cuánto peso justifica consultar?","respuesta":"2 kg en 2-3 días."},{"pregunta":"¿Qué signos alarman?","respuesta":"Disnea, edema, mareo y menor diuresis."},{"pregunta":"¿Qué vacunas se revisan?","respuesta":"Influenza, neumococo y COVID según indicación."}],"resumen":["El peso diario detecta congestión.","La sal se reduce.","Los signos de alarma se conocen.","La vacunación previene complicaciones."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"}],"imagenes":[{"ubicacion":"Sección de autocuidado","descripcion":"Paciente pesándose y revisando etiquetas de sal.","alt":"Educación y autocuidado en insuficiencia cardíaca"}],"keywords":["educación insuficiencia cardíaca","peso diario ic","sal ic","vacunación ic"],"mapa":{"centro":"Autocuidado en IC","ramas":[{"titulo":"Peso","icono":"Scale","nodos":["Diario","2 kg","Consultar"]},{"titulo":"Sal","icono":"Wheat","nodos":["Etiquetas","Procesados","Cocina"]},{"titulo":"Alarma","icono":"AlertTriangle","nodos":["Disnea","Edema","Mareo"]},{"titulo":"Prevención","icono":"ShieldCheck","nodos":["Vacunas","Adherencia","Control"]}]},"proceso":{"titulo":"Plan educativo","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Conocimientos y barreras.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Enseñar","detalle":"Peso, sal y alarma.","icono":"GraduationCap","evidencia":"Educación."},{"titulo":"Acordar","detalle":"Una meta pequeña.","icono":"Target","evidencia":"Acuerdo."},{"titulo":"Registrar","detalle":"Peso y síntomas.","icono":"ClipboardList","evidencia":"Registro."},{"titulo":"Revisar","detalle":"Progreso y vacunas.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Dos kilos en tres días","contexto":"Paciente con IC que sube 2 kg y no tiene disnea.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Esperar a que aparezca disnea.","correcta":false,"retro":"La ganancia de peso es un signo temprano."},{"texto":"Consultar y revisar adherencia, sal y diurético.","correcta":true,"retro":"Se previene la descompensación."},{"texto":"Aumentar la sal.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Educación al paciente con IC y autocuidado: signos de alarma, peso diario, sal, adherencia y vacunación$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Educación al paciente con IC y autocuidado: signos de alarma, peso diario, sal, adherencia y vacunación$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
