  -- 04. Caso integrador: hombre de 72 años en Bogotá reingresado por IC descompensada, con polifarmacia, ERC y automedicación
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"El reingreso que se podía evitar","texto":"Un hombre de 72 años en Bogotá reingresa por disnea y edema. Toma nueve medicamentos, un AINE para el dolor y un producto natural. La FEVI es 32 %, la TFG 35 y el potasio 5,4. El caso integra IC, ERC, polifarmacia, automedicación y educación."},"objetivos":["Integrar los conocimientos del curso.","Priorizar problemas de seguridad.","Ajustar el esquema en ERC.","Diseñar educación y seguimiento."],"conceptos":[{"icono":"Layers","termino":"Polifarmacia","definicion":"Múltiples fármacos con riesgo de interacciones."},{"icono":"AlertTriangle","termino":"Automedicación","definicion":"Uso de AINE o productos sin control."},{"icono":"Droplets","termino":"ERC","definicion":"Requiere ajuste y control de potasio."},{"icono":"Users","termino":"Educación","definicion":"Peso, sal, alarma y adherencia."}],"secciones":[{"titulo":"Evaluación","parrafos":["Se revisan congestión, presión, función renal, potasio y medicamentos. El AINE y el producto natural son riesgos. La polifarmacia exige revisar duplicidades e interacciones.","La meta es estabilizar y optimizar la terapia fundamental."]},{"titulo":"Intervención","parrafos":["Se suspende el AINE y el producto no verificado. Se ajustan los pilares según presión, renal y potasio. Se revisan diuréticos y educación.","El QF documenta y coordina."]},{"titulo":"Seguimiento","parrafos":["Se revisan peso, presión, potasio, TFG y adherencia. La educación y el seguimiento temprano reducen reingresos.","La continuidad es clave.","El plan integrador incluye control presencial a la semana con peso, presión, potasio y creatinina, y contacto telefónico a las 48 horas para verificar adherencia y síntomas. Se acuerda con el médico tratante la secuencia de titulación y se deja por escrito qué hacer si el peso sube, si aparece mareo o si el potasio se eleva. Se revisan vacunas, acceso a medicamentos y apoyo familiar. La automedicación se aborda sin juicios, explicando por qué el AINE y el producto natural son riesgosos y ofreciendo alternativas para el dolor. El caso enseña que la seguridad en IC se construye con revisiones sistemáticas, comunicación entre niveles y educación sostenida, no con una sola intervención aislada. Documentar cada decisión y su justificación permite que cualquier profesional continúe el plan sin perder información."]}],"errores":[{"error":"No revisar productos naturales.","correccion":"Pueden interactuar."},{"error":"No ajustar por TFG.","correccion":"Riesgo de toxicidad."},{"error":"No educar.","correccion":"La automedicación continúa."}],"comprueba":[{"pregunta":"¿Qué se suspende?","respuesta":"AINE y producto no verificado."},{"pregunta":"¿Qué se ajusta?","respuesta":"Pilares y diurético según renal y potasio."},{"pregunta":"¿Qué se controla?","respuesta":"Peso, presión, potasio y TFG."}],"resumen":["La polifarmacia exige revisión.","La automedicación es un riesgo.","El ajuste renal es clave.","La educación previene reingresos."],"referencias":[{"cita":"European Society of Cardiology. 2026 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2026.","url":"https://www.escardio.org/Guidelines/Clinical-Practice-Guidelines/Heart-Failure"},{"cita":"INVIMA. Alertas sanitarias.","url":"https://www.invima.gov.co/alertas-sanitarias"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente mayor con nueve medicamentos, AINE y un producto natural.","alt":"Caso integrador de insuficiencia cardíaca"}],"keywords":["caso integrador insuficiencia cardíaca","polifarmacia ic","automedicación ic","erc ic"],"mapa":{"centro":"Caso integrador","ramas":[{"titulo":"IC","icono":"Activity","nodos":["FEVI 32","Congestión","Pilares"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG 35","Potasio","Ajuste"]},{"titulo":"Fármacos","icono":"AlertTriangle","nodos":["AINE","Natural","Interacciones"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Adherencia","Peso","Control"]}]},"proceso":{"titulo":"Abordaje integrador","intro":"","pasos":[{"titulo":"Revisar","detalle":"Medicación y productos.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Priorizar","detalle":"Seguridad y congestión.","icono":"AlertTriangle","evidencia":"Prioridad."},{"titulo":"Ajustar","detalle":"Pilares y diurético.","icono":"Pill","evidencia":"Plan."},{"titulo":"Educar","detalle":"Peso, sal y alarma.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Renal, potasio y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Nueve fármacos y un AINE","contexto":"Paciente de 72 años con IC, ERC, nueve fármacos, AINE y producto natural.","pregunta":"¿Qué prioridad?","opciones":[{"texto":"Añadir otro fármaco.","correcta":false,"retro":"Primero hay que revisar."},{"texto":"Suspender AINE y producto no verificado, ajustar pilares y educar.","correcta":true,"retro":"La seguridad es primero."},{"texto":"Mantener todo.","correcta":false,"retro":"Riesgo de reingreso."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
