  -- 05. Ficha: Sacubitrilo/valsartán
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha del ARNI","texto":"Sacubitrilo/valsartán es un pilar en la IC con FEVI reducida. Esta ficha resume inicio, titulación, transición desde IECA y seguridad para la dispensación."},"objetivos":["Recordar dosis e indicaciones.","Aplicar la transición desde IECA.","Reconocer efectos adversos.","Educar al paciente."],"conceptos":[{"icono":"Pill","termino":"ARNI","definicion":"Sacubitrilo y valsartán."},{"icono":"Timer","termino":"36 horas","definicion":"Espera tras IECA."},{"icono":"Target","termino":"Dosis","definicion":"24/26 mg cada 12 horas, titulación."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Hipotensión, potasio y angioedema."}],"secciones":[{"titulo":"Dosis","parrafos":["Se inicia con 24/26 mg cada 12 horas y se titula cada dos a cuatro semanas hasta 97/103 mg cada 12 horas, según tolerancia. Se controlan presión, potasio y función renal.","Se usa en FEVI reducida en pacientes que toleran IECA/ARA-II.","El estudio PARADIGM-HF mostró reducción de hospitalización y muerte cardiovascular frente a enalapril en IC con FEVI reducida. No se inicia si hay hipotensión sintomática, potasio mayor de 5,5 mEq/L, TFG menor de 30 o antecedente de angioedema. En adultos mayores y en pacientes con presión limítrofe se prefiere la dosis baja y una titulación más lenta. La evidencia en FEVI preservada es limitada; la elección depende del fenotipo. El costo y la disponibilidad pueden dificultar la continuidad, por lo que el QF verifica el acceso y evita interrupciones. Se recomienda control de presión, potasio y creatinina entre una y dos semanas después de cada ajuste, y educación sobre el riesgo de angioedema y la prohibición de combinar con IECA. La transición debe quedar registrada en la historia clínica y en la fórmula para evitar duplicidades. Si el paciente olvida una dosis, se indica no duplicar y continuar el esquema habitual. La dosis se ajusta también si aparece hipotensión ortostática o deterioro renal."]},{"titulo":"Transición","parrafos":["Si viene de IECA, se suspende y se espera al menos 36 horas. Si viene de ARA-II, no se requiere esa espera. No se combina con IECA.","La educación sobre angioedema es obligatoria."]},{"titulo":"Seguridad","parrafos":["Puede causar hipotensión, hiperpotasemia y deterioro renal. Se controlan electrolitos y función renal. Está contraindicado en embarazo y antecedente de angioedema por IECA.","La revisión de la adherencia y del acceso es parte del plan."]}],"errores":[{"error":"No esperar 36 horas.","correccion":"Riesgo de angioedema."},{"error":"Combinar con IECA.","correccion":"Contraindicado."},{"error":"No controlar potasio.","correccion":"Riesgo de hiperpotasemia."}],"comprueba":[{"pregunta":"¿Dosis inicial?","respuesta":"24/26 mg cada 12 horas."},{"pregunta":"¿Cuánto esperar tras IECA?","respuesta":"36 horas."},{"pregunta":"¿Qué se controla?","respuesta":"Presión, potasio y renal."}],"resumen":["ARNI: pilar en FEVI reducida.","Esperar 36 horas tras IECA.","Controlar presión y potasio.","Educar sobre angioedema."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Entresto 24 mg/26 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/1151058001/FT_1151058001.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con dosis, transición y seguridad.","alt":"Ficha rápida de sacubitrilo/valsartán"}],"keywords":["sacubitrilo valsartán ficha","entresto dosis","transición ieca arni"],"mapa":{"centro":"Sacubitrilo/valsartán","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["24/26 mg","Cada 12 h","Titular"]},{"titulo":"Transición","icono":"Timer","nodos":["Suspender IECA","36 h","Iniciar"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Presión","Potasio","Angioedema"]},{"titulo":"Educación","icono":"Users","nodos":["No IECA","Adherencia","Control"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"FEVI reducida.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Transición","detalle":"36 horas si venía de IECA.","icono":"Timer","evidencia":"Registro."},{"titulo":"Dosis","detalle":"24/26 mg cada 12 h.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Educación","detalle":"Angioedema y control.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Presión, potasio y renal.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Cambio desde enalapril","contexto":"Paciente con enalapril que cambia a ARNI.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Iniciar el mismo día.","correcta":false,"retro":"Debe esperar 36 horas."},{"texto":"Suspender IECA, esperar 36 horas e iniciar.","correcta":true,"retro":"Transición segura."},{"texto":"Combinar ambos.","correcta":false,"retro":"No se combinan."}]}}$j$::jsonb;
