  -- 06. Ficha: Dapagliflozina
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de dapagliflozina","texto":"Dapagliflozina es un iSGLT2 con beneficio en IC. Esta ficha resume dosis, seguridad y educación."},"objetivos":["Recordar dosis e indicaciones.","Reconocer efectos adversos.","Aplicar reglas de días de enfermedad.","Educar al paciente."],"conceptos":[{"icono":"Gauge","termino":"iSGLT2","definicion":"Inhibidor renal."},{"icono":"Target","termino":"Dosis","definicion":"10 mg al día."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Infecciones, volumen y cetoacidosis."},{"icono":"ShieldCheck","termino":"Días de enfermedad","definicion":"Suspender en cirugía o enfermedad aguda."}],"secciones":[{"titulo":"Dosis","parrafos":["La dosis es 10 mg una vez al día. Se usa en IC con FEVI reducida, levemente reducida y preservada, y en enfermedad renal. Requiere revisar la TFG y el volumen.","El beneficio no depende de la diabetes.","Los ensayos DAPA-HF y DELIVER demostraron menos deterioro, hospitalización y muerte cardiovascular en FEVI reducida y preservada. El inicio no exige una TFG alta: puede comenzar con TFG desde 20-25 mL/min y mantenerse hasta el inicio de diálisis, según ficha técnica. El efecto diurético es leve, pero en pacientes con volumen límite puede requerir ajuste del diurético de asa. No se recomienda combinarla con otro iSGLT2. La evidencia es consistente en diabetes y sin ella, y el beneficio aparece en semanas. El QF revisa hidratación, presión y diuréticos, y refuerza la higiene genital. La suspensión perioperatoria suele indicarse tres a cuatro días antes según protocolo institucional, y se reinicia cuando el paciente tolera la vía oral y está estable."]},{"titulo":"Seguridad","parrafos":["Puede causar infecciones genitales, depleción de volumen y cetoacidosis euglucémica. Se suspende en cirugía, enfermedad aguda o ayuno prolongado. Se revisan diuréticos y presión.","La higiene y la hidratación reducen complicaciones."]},{"titulo":"Educación","parrafos":["El paciente debe saber que el fármaco protege el corazón y que debe reportar signos de infección o cetoacidosis. La adherencia y el control son parte del plan.","Se explica al paciente que el fármaco no es solo para la diabetes y que debe continuarlo aunque la glucosa sea normal. Se advierte sobre signos de cetoacidosis: náuseas, dolor abdominal, respiración rápida y malestar general, incluso con glucosa normal. También se enseñan signos de infección genital o urinaria y la importancia de la hidratación. En días de enfermedad con vómito, diarrea o ayuno se suspende temporalmente y se consulta. Estas instrucciones se entregan por escrito y se verifican con teach-back. La adherencia se revisa en cada entrega y se resuelven dudas sobre el uso conjunto con otros pilares.","La ficha resumen no sustituye la ficha técnica."]}],"errores":[{"error":"No revisar TFG.","correccion":"Ajuste y seguridad."},{"error":"No educar sobre cetoacidosis.","correccion":"Rara pero grave."},{"error":"No revisar volumen.","correccion":"Hipotensión."}],"comprueba":[{"pregunta":"¿Dosis?","respuesta":"10 mg al día."},{"pregunta":"¿Beneficio?","respuesta":"Menos hospitalizaciones y muerte cardiovascular."},{"pregunta":"¿Cuándo suspender?","respuesta":"En cirugía o enfermedad aguda."}],"resumen":["Dapagliflozina: 10 mg/día.","Beneficio cardiorrenal.","Vigilar volumen e infecciones.","Reglas de días de enfermedad."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Dapagliflozina Aurovitas 10 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/89963/FT_89963.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con dosis, beneficio y seguridad.","alt":"Ficha rápida de dapagliflozina"}],"keywords":["dapagliflozina ficha","dapagliflozina ic","dapagliflozina dosis"],"mapa":{"centro":"Dapagliflozina","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["10 mg","Una vez","Sin ajuste"]},{"titulo":"Beneficio","icono":"Activity","nodos":["Hospitalización","Mortalidad","Riñón"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Infecciones","Volumen","Cetoacidosis"]},{"titulo":"Educación","icono":"Users","nodos":["Hidratación","Higiene","Suspensión"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"IC o ERC.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Dosis","detalle":"10 mg al día.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Volumen e infecciones.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"Días de enfermedad.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"TFG y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Cirugía programada","contexto":"Paciente con dapagliflozina y cirugía.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Continuar hasta el día de la cirugía.","correcta":false,"retro":"Se suspende según protocolo."},{"texto":"Suspender antes y reiniciar cuando esté estable.","correcta":true,"retro":"Evita cetoacidosis."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Nunca."}]}}$j$::jsonb;
