  -- 07. Ficha: Espironolactona
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de espironolactona","texto":"Espironolactona es un ARM con beneficio en IC. Esta ficha resume dosis, potasio y educación."},"objetivos":["Recordar dosis e indicaciones.","Aplicar control de potasio.","Reconocer efectos adversos.","Educar al paciente."],"conceptos":[{"icono":"Droplets","termino":"ARM","definicion":"Antagonista mineralocorticoide."},{"icono":"Target","termino":"Dosis","definicion":"25 mg al día, hasta 50 mg."},{"icono":"AlertTriangle","termino":"Potasio","definicion":"Riesgo de hiperpotasemia."},{"icono":"Users","termino":"Educación","definicion":"Control y adherencia."}],"secciones":[{"titulo":"Dosis","parrafos":["Se inicia con 25 mg al día y se puede aumentar a 50 mg si se tolera. Se usa en FEVI reducida y en HTA resistente. Se controlan potasio y creatinina.","La dosis se ajusta según la función renal y el potasio.","El estudio RALES demostró menor mortalidad en IC con FEVI reducida; en FEVI preservada el beneficio es incierto y el uso se individualiza. No se inicia con potasio mayor de 5 mEq/L, TFG menor de 30 ni creatinina elevada sin valoración. Se controla potasio y creatinina a la semana, al mes y luego cada tres a seis meses, y después de cualquier cambio de dosis o de la función renal. La dosis puede reducirse a 12,5 mg o interrumpirse si el potasio sube. La eplerenona es una alternativa con menos ginecomastia. Se revisan suplementos de potasio, sales de reemplazo, trimetoprim, AINE y otros fármacos que retienen potasio. La educación incluye reconocer debilidad, palpitaciones o parestesias, y no automedicarse."]},{"titulo":"Seguridad","parrafos":["La hiperpotasemia es el riesgo principal. La ginecomastia y las alteraciones menstruales son frecuentes. Se revisan suplementos y fármacos que retienen potasio.","No se inicia con potasio alto o TFG muy baja.","En pacientes con IECA o ARA-II, la combinación es estándar pero exige control cercano. La diarrea, la deshidratación y los cambios de diurético alteran el potasio y obligan a revisar el esquema. La ginecomastia dolorosa afecta la adherencia y justifica cambiar a eplerenona. El QF documenta cada control y coordina con el médico antes de suspender. En la dispensación se verifica que la fórmula no duplique diuréticos ahorradores de potasio y que el paciente entienda la diferencia entre este fármaco y un suplemento. También se revisa el potasio de los alimentos y las sales de reemplazo."]},{"titulo":"Educación","parrafos":["El paciente debe conocer los síntomas de hiperpotasemia y la importancia de los controles. La adherencia es clave.","La ficha resumen no sustituye la ficha técnica."]}],"errores":[{"error":"No controlar potasio.","correccion":"Riesgo de arritmias."},{"error":"No revisar ginecomastia.","correccion":"Afecta la adherencia."},{"error":"No revisar la TFG.","correccion":"Riesgo de acumulación."}],"comprueba":[{"pregunta":"¿Dosis inicial?","respuesta":"25 mg al día."},{"pregunta":"¿Riesgo principal?","respuesta":"Hiperpotasemia."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio y creatinina."}],"resumen":["Espironolactona: ARM.","25-50 mg al día.","Controlar potasio.","Ginecomastia frecuente."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Espironolactona Accord 25 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/81034/FT_81034.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con dosis, potasio y ginecomastia.","alt":"Ficha rápida de espironolactona"}],"keywords":["espironolactona ficha","espironolactona ic","espironolactona potasio"],"mapa":{"centro":"Espironolactona","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["25 mg","50 mg","Una vez"]},{"titulo":"Indicación","icono":"Target","nodos":["FEVI reducida","IC","HTA resistente"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Potasio","TFG","Ginecomastia"]},{"titulo":"Educación","icono":"Users","nodos":["No suplementos","Control","Adherencia"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"FEVI reducida.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Potasio","detalle":"Revisar antes.","icono":"Droplets","evidencia":"Resultado."},{"titulo":"Dosis","detalle":"25 mg al día.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Educación","detalle":"No suplementos.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Potasio y renal.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Potasio alto","contexto":"Paciente con espironolactona y potasio 5,6.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Aumentar la dosis.","correcta":false,"retro":"Empeora."},{"texto":"Reducir o suspender y controlar.","correcta":true,"retro":"Seguridad primero."},{"texto":"Añadir potasio.","correcta":false,"retro":"Peligroso."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Ficha: Espironolactona$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Ficha: Espironolactona$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 08. Ficha: Furosemida
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de furosemida","texto":"Furosemida es el diurético de asa más usado en IC. Esta ficha resume dosis, ajuste y educación."},"objetivos":["Recordar dosis y vías.","Aplicar ajuste según congestión.","Reconocer efectos adversos.","Educar al paciente."],"conceptos":[{"icono":"Droplets","termino":"Asa","definicion":"Diurético potente."},{"icono":"Target","termino":"Dosis","definicion":"Individualizada según congestión."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Hipopotasemia, volumen y renal."},{"icono":"Users","termino":"Educación","definicion":"Peso y síntomas."}],"secciones":[{"titulo":"Dosis","parrafos":["La dosis es individualizada. La vía oral se usa si hay absorción; la intravenosa en congestión grave o resistencia. Se ajusta según peso, diuresis y síntomas.","Se controlan potasio, presión y función renal.","La biodisponibilidad oral es variable, cercana al 50 %, por lo que una dosis intravenosa equivale aproximadamente al doble por vía oral. En la descompensación aguda se prefiere la vía intravenosa y se ajusta según diuresis, peso y síntomas. La resistencia diurética se maneja aumentando la dosis, fraccionando la administración o combinando con una tiazida como la metolazona, siempre con control estrecho. No se usa de rutina si no hay congestión, porque puede causar deshidratación y deterioro renal. Se controlan potasio, magnesio, creatinina y presión, y se revisa la adherencia y la ingesta de sal."]},{"titulo":"Seguridad","parrafos":["Puede causar hipopotasemia, hipotensión, deshidratación y deterioro renal. La ototoxicidad es rara con dosis altas. Se revisan electrolitos.","La educación sobre peso y síntomas es parte del plan.","La hipopotasemia favorece arritmias y requiere reposición o ajuste. La deshidratación y la hipotensión son frecuentes en adultos mayores y en combinación con iSGLT2 u otros diuréticos. La ototoxicidad aparece con dosis altas y administración rápida por vía intravenosa, por lo que se infunde lentamente. En la dispensación se verifica la indicación, la dosis acumulada y el control de electrolitos. El paciente debe saber que la furosemida no reemplaza la restricción de sal y que el peso diario guía los ajustes. Se documenta el plan y se coordina con el equipo para evitar duplicidades."]},{"titulo":"Educación","parrafos":["El paciente debe registrar el peso y consultar si aumenta o si aparece disnea. La adherencia y el ajuste acordado son clave.","Se entrega un esquema por escrito con la dosis, los horarios y qué hacer si sube el peso. Se advierte que la toma nocturna puede fragmentar el sueño y que la pérdida excesiva de orina con mareo requiere consulta. La revisión periódica del botiquín detecta duplicidades y productos con efecto diurético.","La ficha resumen no sustituye la ficha técnica."]}],"errores":[{"error":"No controlar potasio.","correccion":"Hipopotasemia."},{"error":"No revisar peso.","correccion":"Clave para ajuste."},{"error":"No educar.","correccion":"Adherencia."}],"comprueba":[{"pregunta":"¿Vías?","respuesta":"Oral e intravenosa."},{"pregunta":"¿Qué se controla?","respuesta":"Potasio, presión y renal."},{"pregunta":"¿Qué educar?","respuesta":"Peso y síntomas."}],"resumen":["Furosemida: diurético de asa.","Dosis individualizada.","Controlar electrolitos.","Educar sobre peso."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Furosemida Cinfa 40 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/22974/FT_22974.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con dosis, electrolitos y peso.","alt":"Ficha rápida de furosemida"}],"keywords":["furosemida ficha","furosemida ic","furosemida dosis"],"mapa":{"centro":"Furosemida","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["Oral","IV","Ajuste"]},{"titulo":"Indicación","icono":"Target","nodos":["Congestión","Edema","IC"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Potasio","Presión","Renal"]},{"titulo":"Educación","icono":"Users","nodos":["Peso","Alarma","Adherencia"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"Congestión.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Dosis","detalle":"Individualizada.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Potasio y renal.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"Peso y alarma.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Síntomas y electrolitos.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Edema persistente","contexto":"Paciente con furosemida y edema.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Mantener la dosis.","correcta":false,"retro":"La congestión persiste."},{"texto":"Revisar dosis, adherencia y renal, y ajustar.","correcta":true,"retro":"La respuesta guía."},{"texto":"Suspender.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
