  -- 09. Ficha: Carvedilol
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de carvedilol","texto":"Carvedilol es un betabloqueador con efecto alfa y evidencia en IC. Esta ficha resume dosis, titulación y seguridad."},"objetivos":["Recordar dosis e indicaciones.","Aplicar titulación.","Reconocer efectos adversos.","Educar al paciente."],"conceptos":[{"icono":"Activity","termino":"Betabloqueador","definicion":"Bloquea beta y alfa."},{"icono":"Target","termino":"Dosis","definicion":"3,125 mg cada 12 horas, titulación."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Bradicardia, hipotensión y fatiga."},{"icono":"Users","termino":"Educación","definicion":"No suspender bruscamente."}],"secciones":[{"titulo":"Dosis","parrafos":["Se inicia con 3,125 mg cada 12 horas y se titula cada dos semanas hasta la dosis tolerada. Se usa en FEVI reducida y postinfarto. Se controlan frecuencia y presión.","La titulación es gradual.","Los ensayos COPERNICUS y US Carvedilol demostraron menor mortalidad en IC con FEVI reducida. No se inicia durante la descompensación con congestión o inestabilidad; se espera a que el paciente esté estable y sin necesidad de diurético intravenoso. La dosis objetivo es 25 mg cada 12 horas, o 50 mg cada 12 horas si pesa más de 85 kg. La titulación se hace cada dos semanas si no hay bradicardia, hipotensión sintomática ni empeoramiento de la IC. Se administra con alimentos para reducir la hipotensión ortostática. La suspensión brusca puede precipitar angina o arritmias, por lo que se retira de forma gradual."]},{"titulo":"Seguridad","parrafos":["Puede causar bradicardia, hipotensión, fatiga y broncoespasmo. Se usa con precaución en asma. No se suspende bruscamente.","La educación es parte del plan.","Se usa con precaución en asma y EPOC por riesgo de broncoespasmo, y se evita combinar con verapamilo o diltiazem por bradicardia e hipotensión. En diabetes puede enmascarar los síntomas de hipoglucemia, por lo que se educa al paciente. Se revisan frecuencia, presión y síntomas en cada ajuste. La fatiga transitoria no siempre obliga a suspender; se distingue del empeoramiento de la IC. En la dispensación se verifica que no haya otro betabloqueador duplicado y que el paciente sepa que no debe suspenderlo sin indicación médica."]},{"titulo":"Educación","parrafos":["El paciente debe reportar mareo, fatiga o falta de aire. La adherencia y el control son clave.","Se explica que el beneficio aparece con el tiempo y que la sensación de cansancio inicial suele mejorar. Se recomienda levantarse despacio para evitar mareo y reportar pulso lento, falta de aire o aumento de peso.","La ficha resumen no sustituye la ficha técnica."]}],"errores":[{"error":"Suspender bruscamente.","correccion":"Riesgo de rebote."},{"error":"No controlar frecuencia.","correccion":"Bradicardia."},{"error":"No revisar asma.","correccion":"Broncoespasmo."}],"comprueba":[{"pregunta":"¿Dosis inicial?","respuesta":"3,125 mg cada 12 horas."},{"pregunta":"¿Qué se controla?","respuesta":"Frecuencia y presión."},{"pregunta":"¿Se suspende bruscamente?","respuesta":"No."}],"resumen":["Carvedilol: beta y alfa.","Inicio 3,125 mg cada 12 h.","Titulación gradual.","No suspender bruscamente."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Carvedilol Cinfa 25 mg comprimidos EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68328/FT_68328.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con dosis, frecuencia y educación.","alt":"Ficha rápida de carvedilol"}],"keywords":["carvedilol ficha","carvedilol ic","carvedilol dosis"],"mapa":{"centro":"Carvedilol","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["3,125 mg","Cada 12 h","Titular"]},{"titulo":"Indicación","icono":"Target","nodos":["FEVI reducida","IC","Postinfarto"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Bradicardia","Hipotensión","Fatiga"]},{"titulo":"Educación","icono":"Users","nodos":["No suspender","Adherencia","Control"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"FEVI reducida.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Dosis","detalle":"3,125 mg cada 12 h.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Frecuencia y presión.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"No suspender.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Síntomas y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Bradicardia","contexto":"Paciente con carvedilol y frecuencia 50.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Aumentar la dosis.","correcta":false,"retro":"Empeora."},{"texto":"Revisar síntomas y ajustar la dosis.","correcta":true,"retro":"Seguridad primero."},{"texto":"Suspender bruscamente.","correcta":false,"retro":"Riesgo de rebote."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
